INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('14467e05-f2cf-420e-832a-ea1c68386e98', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '9ca34038-1a65-4ede-88c5-1492ab4bc249', 'theIntention', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('d31ce6e7-04b8-4294-b4c1-905b9f8c4710', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '9ca34038-1a65-4ede-88c5-1492ab4bc249', 'This string represents instructions, intentions, or interpretations in natural language. It grounds the structure to reality.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('288a7e93-4b08-4cbb-95d7-826ecf0df7e7', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '05d61805-e171-4bdc-a770-3cf2ed75cf44', 'theDescription', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('5c49a71f-e9c0-4bc7-967b-b626deb4153d', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '05d61805-e171-4bdc-a770-3cf2ed75cf44', 'A longer, paragraph-plus natural-language description of the item -- more substantial than aNote''s deliberately-unspecified free text.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('9526a738-7cfe-4187-b129-b897d34aba16', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '90c2b9bb-ff6b-4f84-a29b-7b9e8dcfe04a', 'aComponent', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('d7df1f15-1b3b-441b-ae0b-90e8d153fbe6', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '90c2b9bb-ff6b-4f84-a29b-7b9e8dcfe04a', 'Tags an entity as belonging to a category, so entities sharing that category can be validated for a shared shape.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('d1d1af29-ead0-45bc-90b1-1ffed6641130', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '8e37c137-4791-470c-8af2-f9ef087d76f6', 'SlotCriteria', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('31fbba4e-fa5b-4144-ba47-7a7188d24e08', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8e37c137-4791-470c-8af2-f9ef087d76f6', 'Tags an attribute as one that declares a slot relationship between a component and an attribute it expects members to carry -- regardless of whether that expectation is enforced as an error, a warning, or purely informational.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('a3ef08c0-948f-4e50-b3d0-b8849070da7c', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '24762266-9337-4930-b88c-55b6af4e7642', 'aRequiredSlot', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('bde23fa0-2710-4b6b-a6d7-37841135b6e4', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '24762266-9337-4930-b88c-55b6af4e7642', 'Declares that entities carrying a given component must have at least one statement using the given attribute, for validation purposes.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('58a39014-c8d9-4208-a32e-3e31ecb92bf3', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '8a707bcb-7ff7-488f-b7e3-b1679f823c95', 'aDesirableSlot', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('53a22b50-4418-470a-9ce0-184711e8d733', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8a707bcb-7ff7-488f-b7e3-b1679f823c95', 'Declares that entities carrying a given component are expected to have at least one statement using the given attribute; absence is worth a warning, not an error, and signals data worth completing.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('1954e11a-9f58-4142-a48b-c54d0cb418fe', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', 'e8d0e88d-a8ea-4612-8e8c-a4be732d1a93', 'anOptionalSlot', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('1851288a-8f16-4efb-b0b0-84a4d6c4238e', '9ca34038-1a65-4ede-88c5-1492ab4bc249', 'e8d0e88d-a8ea-4612-8e8c-a4be732d1a93', 'Declares that entities carrying a given component may have this attribute, for table and schema discovery purposes only -- its absence has no validation consequence.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('32d7d69b-66fa-4dbd-a2bc-84c7918deabb', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', 'd9496c5d-6e55-43ca-84bf-72d565c33419', 'theProvenance', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('3aabb29e-14ec-4f01-9c75-fe6e734bd8e0', '9ca34038-1a65-4ede-88c5-1492ab4bc249', 'd9496c5d-6e55-43ca-84bf-72d565c33419', 'Points from a statement''s handle to the ProvenanceInfo entity describing who assembled it and when.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('bf728fef-32a5-47bf-bd6c-ff5b2104b041', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '622966de-0519-4a9b-a2d5-95a99850ba42', 'ProvenanceInfo', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('a4a00469-4886-435c-ba5d-c3aa7750c774', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '622966de-0519-4a9b-a2d5-95a99850ba42', 'A way to tell who put this information together and when.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('6837e181-2cc9-4b53-8975-fee30eec2ec3', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '0cacaa3b-d1be-4314-9644-a65baff03a63', 'theSelfDescribingProvenance', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('c6d2ac4a-5c7a-4f0e-83f3-eb520262fcf3', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '0cacaa3b-d1be-4314-9644-a65baff03a63', 'Used exactly once per ProvenanceInfo entity, pointing it at itself. Terminates the regress of every provenance statement needing its own provenance -- the same trick as theName of theName.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('a16db42d-2f51-4f53-8b96-f1dec240023b', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '8f9dc95b-c4d3-4500-9a6c-9ddc63cdecf9', 'aReplacement', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('8af1b1af-c62f-4020-958e-f2c3f15b5b9f', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8f9dc95b-c4d3-4500-9a6c-9ddc63cdecf9', 'Points from an older statement''s handle (or an older entity) to the newer statement or entity that supersedes it. A reader should prefer the value(s) here over the item bearing this statement''s entity, unless something else in turn has an aReplacement pointing away from that item too -- walk the chain to find the current one. Multi-valued: an old item may have been superseded by more than one new item (e.g. split into two). Nothing in this store carries a timestamp, so recency is inferred only by following this chain, never by row order.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('b1f5f752-d0b5-466a-a6fd-2b280e0041f6', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '1c260a46-c907-4efc-adb2-9345aebd9500', 'anErratum', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('2488053a-c2b3-415a-9433-d2d49d18e158', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '1c260a46-c907-4efc-adb2-9345aebd9500', 'Free text flagging that the statement or entity carrying this (by UUID) should never have existed as asserted -- a mistake, not a later legitimate change. Multi-valued (anErratum, not theErratum) since an item could be wrong for more than one reason. Distinct from aReplacement, which chains a sequence of states each true in their own time -- anErratum instead marks something void from the start. Could become a full component later if a flagged item ever needs more than free text attached.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('48236d87-392c-4981-8732-92ab7ac67602', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '29a25e0e-3f32-4787-965e-3ecc917d6fef', 'aNote', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('5a9e4e8a-11eb-4e73-9eec-0a469a6a2bb8', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '29a25e0e-3f32-4787-965e-3ecc917d6fef', 'Free text. Deliberately left unspecified -- no fixed meaning is imposed on what this note should contain.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('e7baa223-1956-4941-98d5-af92166ef8a3', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '9084efd2-1fcf-492e-9ec1-63ef91691f47', 'aReferencedUUID', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('51410ce1-e7fd-49ee-8485-79e42846b785', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '9084efd2-1fcf-492e-9ec1-63ef91691f47', 'Declares that a document or piece of code hardcodes the given UUID because that''s the shape best to operate on. Lets a data steward find every place an item is used -- useful for keeping items up to date, or seeing how an item is used in context.', 'str');
