-- Trunky starter kit: the bootstrap concepts llms.txt documents, plus one
-- seed ProvenanceInfo entity (P0) so a fresh clone's first live API write has
-- something valid to cite (see api_server.py's _check_provenance -- every
-- write, including a new ProvenanceInfo entity, must already point at one).
-- theSelfDescribingProvenance uses the same fixed UUID llms.txt documents;
-- P0 itself is freshly minted per run, on purpose -- see llms.txt's Provenance
-- section for why only the vocabulary is fixed, not the instance.
-- Apply with: sqlite3 lignin.db < starter.sql

CREATE TABLE IF NOT EXISTS statements (
    handle     TEXT PRIMARY KEY,
    attribute  TEXT NOT NULL,
    entity     TEXT NOT NULL,
    value      TEXT NOT NULL,
    value_type TEXT NOT NULL CHECK (value_type IN ('uuid', 'str', 'int'))
);
CREATE INDEX IF NOT EXISTS idx_statements_entity ON statements(entity);
CREATE INDEX IF NOT EXISTS idx_statements_attribute ON statements(attribute);
CREATE INDEX IF NOT EXISTS idx_statements_attr_entity ON statements(attribute, entity);
CREATE INDEX IF NOT EXISTS idx_statements_value ON statements(value);

